  for (const w of ["apple", "avocado", "banana"]) { const k = w[0]; const l = groups[k] || (groups[k] = []); l.push(w); }
  console.log(groups);
  const m: Record<string, number[]> = {};
  (m["k"] ??= []).push(1); (m["k"] ??= []).push(2);
  console.log(m, m.k.length, m["k"][1] + 1);
